INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2d5bca67-be16-4c7b-be4f-4ca94560e314', 'Common Area Maintenance Charges', '9', '9', 'A).- GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord a fee for administration and maintenance, which is 5% of the monthly rent plus VAT.\n- This fee is calculated based on the current rent at the time the payment is due.\n- The Tenant cannot demand an account of how these fees are used or influence the management or maintenance of the shopping center.\n- The Landlord must use the funds to maintain, repair, and replace parts of the shopping center to keep it in good working condition.\n- In cases of unforeseen events or force majeure, the Landlord is not responsible for any damages related to service issues at the shopping center.\n- Such issues do not allow the Tenant to terminate the contract, claim hidden defects, or withhold or reduce rent.', E'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 5% del importe de la renta mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.\n\nEn caso fortuito y/o de fuerza mayor, la Arrendadora no será responsable ante la Arrendataria por cualquier daño o perjuicio derivado de la calidad, cantidad, falla, falta de disponibilidad, discontinuidad o interrupción en el suministro de cualquier servicio derivado de la cuota de mantenimiento y/o del Centro Comercial y dichas anomalías no serán: (i) causa de terminación de éste contrato; (ii) consideradas un vicio oculto o defecto de construcción a cargo de la Arrendadora; o (iii) un derecho, motivo o facultad de la Arrendataria para retener o reducir la Renta Mensual o incumplir cualquier otra obligación a su cargo derivada de éste Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2d5bca67-be16-4c7b-be4f-4ca94560e314', 'Late Fees', '15', '16', 'INTERESES MORATORIOS', E'- La tasa de interés por pagos atrasados es del 2% mensual.\n- Se aplica sobre el total de la deuda no pagada a tiempo.\n- El interés se calcula cada mes o parte de mes mientras dure el retraso.\n- Se cuenta desde la fecha en que debía hacerse el pago hasta que se pague por completo.', 'La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa aplicará sobre el importe total del adeudo no cubierto puntualmente. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2d5bca67-be16-4c7b-be4f-4ca94560e314', 'Incremento de Renta', '5', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months from the start of the rent payment.\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and two months before the new adjustment.\n- If the increase percentage is more than 6%, the maximum increase will be capped at 6%.\n- The first rent increase will occur 13 months after the store opens.', E'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, contado a partir de la fecha de inicio de pago de renta, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica: Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de la renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 6% (seis por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.\n\nEl primer incremento será a los 13 (trece) meses siguientes de la Fecha de Apertura del Local.');
