INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17413861-1b54-42b0-a119-edc226dfe55e', 'Percentage Rent', '8', '2', 'CONTRAPRESTACIÓN', E'- If 9% of the NET SALES for the month is more than the Fixed Monthly Rent, the Tenant must pay the Landlord the difference.\n- This additional payment is on top of the Fixed Monthly Rent already paid.\n- The Tenant must also pay the applicable Value Added Tax on this difference.\n- This extra payment is considered Variable Rent.', 'Adicionalmente, si el 9% (nueve por ciento) de las VENTAS NETAS (conforme la definición señalada más adelante) durante el mes que corresponda es superior a la Renta Mensual Fija, la Arrendataria deberá pagar a la Arrendadora, además de lo que hubiese pagado por concepto de Renta Mensual Fija, el total de dicha diferencia más el Impuesto al Valor Agregado correspondiente, misma que se considerará como Renta Variable.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17413861-1b54-42b0-a119-edc226dfe55e', 'Late Fees', '11', '4', 'INTERESES MORATORIOS', E'- Si el inquilino se retrasa en el pago del alquiler, debe pagar intereses por cada día de retraso.\n- Los intereses se calculan multiplicando por 2 la Tasa de Interés Interbancaria de Equilibrio (TIIE) a 28 días.\n- La TIIE se publica por el Banco de México en el Diario Oficial de la Federación.\n- Se utiliza la TIIE del día hábil anterior al día en que el inquilino se retrasa en el pago.', 'En caso de retraso en el pago de la Renta, la Arrendataria se obliga a pagar a la Arrendadora por concepto de intereses moratorios, por cada día que la ARrendataria permanezca en mora, el equivalente a la cantidad que resulte de multiplicar por 2 la Tasa de Interés Interbancaria de Equilibrio a plazo de 28 días publicada por el Banco de México en el Diario Oficial de la Federación ("TIIE") el Día Hábil inmediato anterior al de la fecha en que la Arrendataria incurra en mora de la obligación de pago correspondiente conforme al presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17413861-1b54-42b0-a119-edc226dfe55e', 'Incremento de Renta', '9', '2', 'CONTRAPRESTACIÓN', E'- The fixed monthly rent and additional rent will increase every January, starting in 2025.\n- The increase is based on the market values of the property and an adjustment factor.\n- The adjustment factor is calculated by dividing the most recent National Consumer Price Index (INPC) before the rent increase by the INPC at the start of the lease or the last adjustment.', E'La Renta Mensual Fija y Renta Adicional pactadas en esta Cláusula será incrementada en forma ANUAL, en el mes de enero de cada año, a partir del 01 de enero del 2025 aplicando a dichos conceptos del último mes anterior al ajuste, el factor a que se refiere el párrafo siguiente, así como tomando en consideración los Valores de Mercado aplicables al inmueble en materia de arrendamiento que en su momento rijan y que se encuentren vigentes.\n\nEl factor de ajuste para efectos del párrafo anterior se calculará dividiendo el último INPC publicado en fecha anterior al del mes previo al incremento de la Renta Mensual Fija y Renta Adicional entre el último publicado al mes de inicio del arrendamiento o al mes del último ajuste, según corresponda.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17413861-1b54-42b0-a119-edc226dfe55e', 'Common Area Maintenance Charges', '7', '2', 'CONTRAPRESTACIÓN', E'- The tenant must pay a monthly amount of $67,718.80 MXN, plus applicable VAT, called "Additional Rent."\n- This Additional Rent is used to cover all expenses for maintaining and keeping the property functional.', E'La Arrendataria se obliga a pagar mensualmente, la cantidad de $67,718.80 MN, más el IVA que le corresponda (en adelante la "Renta Adicional").\n\nEl concepto Renta Adicional será un ingreso por arrendamiento destinado a cubrir todos los gastos por la conservación y funcionalidad del inmueble.');
